const tabId = 725790041;
const jjDetails = await browserjs(tabId, () => {
  const text = document.body.innerText;
  const match = text.match(/(Viewing Deck|Jais Flight|ticket|entry|price|AED|hours|timings)[\s\S]{1,400}/gi);
  const links = Array.from(document.querySelectorAll("a")).map(a => ({ text: a.innerText?.trim(), href: a.href })).filter(a => a.text && (a.href.includes("viewing") || a.href.includes("flight") || a.href.includes("book")));
  return {
    matches: match ? match.slice(0, 5) : [],
    links: links.slice(0, 10)
  };
});
console.log("Jebel Jais details:", JSON.stringify(jjDetails, null, 2));

